import{_ as o,o as t,c as d,a2 as r}from"./chunks/framework.BXzK3EA4.js";const u=JSON.parse('{"title":"Flow Editor","description":"","frontmatter":{},"headers":[],"relativePath":"flow-editor/index.md","filePath":"flow-editor/index.md"}'),a={name:"flow-editor/index.md"};function n(i,e,c,s,l,h){return t(),d("div",null,[...e[0]||(e[0]=[r('<h1 id="flow-editor" tabindex="-1">Flow Editor <a class="header-anchor" href="#flow-editor" aria-label="Permalink to &quot;Flow Editor&quot;">​</a></h1><p>Flow is Tradeboard&#39;s node-graph strategy builder at <code>/flow</code>. You wire market data into indicators, indicators into conditions, and conditions into order execution, no Python required.</p><p>This section is the <strong>technical reference</strong>. It assumes you are building a real strategy and want to know exactly what each node does, what the execution model guarantees, and where the boundaries are.</p><ul><li><a href="./concepts.html">Concepts and Execution Model</a>: nodes, edges, variables, how a run actually proceeds</li><li><a href="./node-reference.html">Node Reference</a>: all 61 nodes, their fields and their outputs</li><li><a href="./json-format.html">JSON Format</a>: the import contract, field by field, and how to check a workflow before importing it</li><li><a href="./market-data.html">Market Data and Timeframes</a>: quotes, history, lookback, bar limits</li><li><a href="./indicators.html">Indicators</a>: all 116 indicators, which bar <code>latest</code> is, tuple outputs, nesting</li><li><a href="./tutorials.html">Tutorials</a>: twelve complete strategies, ending with a live 1-minute Supertrend reversal</li><li><a href="./limitations.html">Limitations and Gotchas</a>: read this before going live</li></ul><hr><h2 id="what-flow-can-do" tabindex="-1">What Flow can do <a class="header-anchor" href="#what-flow-can-do" aria-label="Permalink to &quot;What Flow can do&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Capability</th><th>Nodes</th></tr></thead><tbody><tr><td>Trigger on a schedule, a webhook, a price level, or an order fill</td><td><code>start</code>, <code>webhookTrigger</code>, <code>priceAlert</code>, <code>orderUpdateTrigger</code></td></tr><tr><td>Run a schedule on the clock, inside a configurable market-hours window</td><td><code>start</code> (<code>marketHoursOnly</code>, <code>marketHoursStart/End/Exchange</code>)</td></tr><tr><td>Read live quotes and market depth</td><td><code>getQuote</code>, <code>multiQuotes</code>, <code>getDepth</code>, <code>subscribeLtp/Quote/Depth</code>, <code>unsubscribe</code></td></tr><tr><td>Read historical OHLCV at any supported timeframe</td><td><code>history</code>, <code>barOffset</code>, <code>priorPeriodOhlc</code></td></tr><tr><td>Compute any of 116 technical indicators</td><td><code>indicator</code></td></tr><tr><td>Branch on price, time, position, funds, or any computed value</td><td><code>priceCondition</code>, <code>timeWindow</code>, <code>timeCondition</code>, <code>positionCheck</code>, <code>fundCheck</code>, <code>varCondition</code></td></tr><tr><td>Combine conditions</td><td><code>andGate</code>, <code>orGate</code>, <code>notGate</code></td></tr><tr><td>Place equity, futures, and options orders</td><td><code>placeOrder</code>, <code>smartOrder</code>, <code>optionsOrder</code>, <code>optionsMultiOrder</code>, <code>basketOrder</code>, <code>splitOrder</code></td></tr><tr><td>Drive <strong>every</strong> order field from the alert that triggered the run, not just <code>symbol</code></td><td>any order node, using <code>&amp;#123;&amp;#123;webhook.*&amp;#125;&amp;#125;</code> on <code>exchange</code>, <code>action</code>, <code>quantity</code>, <code>product</code>, <code>priceType</code>, <code>price</code>, <code>triggerPrice</code>, <code>offset</code>, <code>optionType</code>, <code>expiryType</code>, <code>positionSize</code>, <code>splitSize</code></td></tr><tr><td>Manage open orders and positions</td><td><code>modifyOrder</code>, <code>cancelOrder</code>, <code>cancelAllOrders</code>, <code>closePositions</code></td></tr><tr><td>Resolve option symbols, expiries, and chains, by relative expiry or an exact <code>DDMMMYY</code> date</td><td><code>optionSymbol</code>, <code>expiry</code>, <code>optionChain</code>, <code>syntheticFuture</code></td></tr><tr><td>Look up contract details and supported intervals</td><td><code>symbol</code>, <code>intervals</code></td></tr><tr><td>Alert and log</td><td><code>telegramAlert</code>, <code>whatsappAlert</code>, <code>log</code>, <code>httpRequest</code></td></tr><tr><td>Track P&amp;L for one strategy, not the account</td><td><code>strategyPnl</code></td></tr><tr><td>Read the account: orders, trades, positions, holdings, funds, margin</td><td><code>orderBook</code>, <code>tradeBook</code>, <code>positionBook</code>, <code>openPosition</code>, <code>holdings</code>, <code>funds</code>, <code>margin</code>, <code>getOrderStatus</code></td></tr><tr><td>Check exchange holidays and market timings</td><td><code>holidays</code>, <code>timings</code></td></tr><tr><td>Detect a new day, week, month, quarter or year</td><td><code>calendar</code></td></tr><tr><td>Pause within a run</td><td><code>delay</code>, <code>waitUntil</code></td></tr><tr><td>Arithmetic and state within a run</td><td><code>mathExpression</code>, <code>variable</code></td></tr></tbody></table><p>61 node types in total, every one documented in the <a href="./node-reference.html">Node Reference</a>, with the JSON each one expects in the <a href="./json-format.html">JSON Format</a> reference. Every order node calls the same service functions as <code>/api/v1/</code>, so Analyzer (sandbox) mode, Action Center approval, and Telegram or WhatsApp alerts all behave identically to an API-placed order.</p><p>A workflow can be checked before it is imported. The <code>flow-builder</code> skill in the Tradeboard repo runs the importer&#39;s own validator and then flags the mistakes that import cleanly and misbehave later, chiefly a <code>data</code> key that no node reads:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>uv run python .claude/skills/flow-builder/validate.py my_workflow.json</span></span></code></pre></div><h2 id="what-flow-cannot-do" tabindex="-1">What Flow cannot do <a class="header-anchor" href="#what-flow-cannot-do" aria-label="Permalink to &quot;What Flow cannot do&quot;">​</a></h2><p>These are hard boundaries, not oversights. <a href="./limitations.html">Limitations</a> covers each in detail with workarounds.</p><table tabindex="0"><thead><tr><th>Limitation</th><th>Practical effect</th></tr></thead><tbody><tr><td><strong>No state across runs</strong></td><td><code>variable</code> values reset every run. &quot;Have I already entered today?&quot; must be answered from the broker (<code>positionCheck</code>, <code>orderBook</code>), not a counter. Period boundaries are the exception: <code>calendar</code> answers &quot;is a new week/month/quarter&quot; from the exchange calendar, no memory needed.</td></tr><tr><td><strong><code>delay</code> and <code>waitUntil</code> block the run</strong></td><td>They hold the execution slot, and for a webhook the triggering HTTP request too, for their full duration. <code>delay</code> is silently capped at 300 seconds and then continues, so a workflow written as &quot;wait 30 minutes&quot; exits after five. <code>waitUntil</code> is capped at 30 minutes and <strong>errors</strong> beyond that rather than waiting. Waiting out a session means a second workflow on its own schedule.</td></tr><tr><td><strong>No loops</strong></td><td>You cannot iterate a symbol list. One workflow handles one symbol; clone it per symbol, or drive one workflow from <code>&amp;#123;&amp;#123;webhook.symbol&amp;#125;&amp;#125;</code>, see <a href="./tutorials.html#11-driving-an-order-from-the-webhook-payload">Tutorial 11</a>.</td></tr><tr><td><strong>No backtesting</strong></td><td>Flow runs forward only. Use the Python Strategy Host or the <code>tradeboard</code> SDK to backtest.</td></tr><tr><td><strong>No pandas objects</strong></td><td>Variables are JSON. You get arrays of records and single values, not a <code>pandas.Series</code>.</td></tr><tr><td><strong>Max 200 bars per fetch</strong></td><td>Deep history (10 years of 1-minute data) is refused by design. See <a href="./market-data.html">Market Data</a>.</td></tr><tr><td><strong>Triggers cannot read upstream data</strong></td><td>A trigger is the entry point, so its fields cannot contain <code>&amp;#123;&amp;#123;variables&amp;#125;&amp;#125;</code>.</td></tr><tr><td><strong>Indicators need one symbol</strong></td><td><code>correlation</code>, <code>beta</code>, <code>crossover</code>, <code>crossunder</code> need two independent series and are not available as a single <code>indicator</code> node. Crossovers are built from two indicator nodes, see <a href="./tutorials.html#3-crossovers">Tutorial 3</a>.</td></tr><tr><td><strong><code>closePositions</code> ignores its filter in live trading</strong></td><td>It honours symbol, exchange and product in Analyzer mode and squares off the <strong>entire book</strong> live, so a filtered node looks correct in sandbox testing. Close a specific leg with <code>smartOrder</code> and <code>positionSize: 0</code> instead.</td></tr><tr><td><strong>An unknown <code>data</code> key is silently ignored</strong></td><td><code>strikeOffset</code> where the field is <code>offset</code> imports cleanly, runs successfully, and leaves the node on its default. Nothing in the run says so. Check the workflow before importing it.</td></tr></tbody></table><h2 id="live-vs-analyzer-mode" tabindex="-1">Live vs Analyzer mode <a class="header-anchor" href="#live-vs-analyzer-mode" aria-label="Permalink to &quot;Live vs Analyzer mode&quot;">​</a></h2><p>Flow does not have its own paper-trading switch. It inherits the global <strong>Analyzer</strong> toggle:</p><ul><li><strong>Analyzer on</strong>: orders are simulated by the Sandbox engine. Order ids are real-looking, <code>mode</code> is <code>analyze</code>, and nothing reaches your broker.</li><li><strong>Analyzer off</strong>: orders go to the live broker.</li></ul><p>Always build and validate a strategy with Analyzer on. Every run log quoted in this section was captured in Analyzer mode against a live broker connection.</p><p>One thing behaves <em>differently</em> between the two, and it is the one place where Analyzer testing can mislead: <code>closePositions</code> honours its symbol, exchange and product filter in Analyzer mode and ignores it live.</p>',18)])])}const m=o(a,[["render",n]]);export{u as __pageData,m as default};
